package local.macphone.companion;
import android.app.*;import android.os.Bundle;import android.net.Uri;import android.provider.Settings;import android.widget.*;import javax.net.ssl.*;import java.security.*;import java.security.cert.*;import org.json.*;import java.io.*;
public class PairActivity extends Activity {
 @Override public void onCreate(Bundle b){super.onCreate(b);Uri uri=getIntent().getData();if(uri==null||!"macphone".equals(uri.getScheme())||!"pair".equals(uri.getHost())){finish();return;}
 final String host=uri.getQueryParameter("host"),port=uri.getQueryParameter("port"),pin=uri.getQueryParameter("pin"),code=uri.getQueryParameter("code"),name=uri.getQueryParameter("name");
 if(host==null||!host.matches("[0-9.]+")||port==null||!port.matches("[0-9]{1,5}")||pin==null||!pin.matches("[a-f0-9]{64}")||code==null||code.length()>128){finish();return;}
 TextView view=new TextView(this);view.setPadding(40,80,40,40);view.setTextSize(18);view.setText("配对电脑："+name+"\n地址："+host+"\n\n请确认这是你自己的 MacPhone 二维码。当前配对不替代ADB连接。");setContentView(view);
 new AlertDialog.Builder(this).setTitle("配对这台电脑？").setMessage(name+"\n"+host).setNegativeButton("取消",(d,w)->finish()).setPositiveButton("确认配对",(d,w)->{view.setText("正在配对…");new Thread(()->{try{
 TrustManager[] trust={new X509TrustManager(){public X509Certificate[] getAcceptedIssuers(){return new X509Certificate[0];}public void checkClientTrusted(X509Certificate[] c,String a)throws CertificateException{throw new CertificateException("Unsupported");}public void checkServerTrusted(X509Certificate[] c,String a)throws CertificateException{try{byte[] hash=MessageDigest.getInstance("SHA-256").digest(c[0].getEncoded());StringBuilder s=new StringBuilder();for(byte x:hash)s.append(String.format("%02x",x));if(!s.toString().equals(pin))throw new CertificateException("电脑身份不匹配");}catch(Exception e){throw new CertificateException(e);}}}};
 SSLContext ssl=SSLContext.getInstance("TLS");ssl.init(null,trust,new SecureRandom());HttpsURLConnection conn=(HttpsURLConnection)new java.net.URL("https://"+host+":"+port+"/pair").openConnection();conn.setSSLSocketFactory(ssl.getSocketFactory());conn.setHostnameVerifier((h,s)->h.equals(host));conn.setConnectTimeout(10000);conn.setReadTimeout(10000);conn.setRequestMethod("POST");conn.setDoOutput(true);conn.setRequestProperty("Content-Type","application/json");String id=Settings.Secure.getString(getContentResolver(),Settings.Secure.ANDROID_ID);byte[] payload=new JSONObject().put("code",code).put("deviceId",id).put("name",android.os.Build.MODEL).toString().getBytes("UTF-8");conn.getOutputStream().write(payload);InputStream stream=conn.getResponseCode()==200?conn.getInputStream():conn.getErrorStream();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buffer=new byte[1024];int n;while((n=stream.read(buffer))!=-1){if(out.size()>8192)throw new Exception("响应过大");out.write(buffer,0,n);}JSONObject result=new JSONObject(out.toString("UTF-8"));conn.disconnect();if(!result.optBoolean("ok"))throw new Exception(result.optString("error","配对失败"));MainActivity.prefs(this).edit().putString("pairedMac",name).putString("pairedMacHost",host).putString("pairedMacPin",pin).apply();runOnUiThread(()->view.setText("已配对："+name+"\n\n局域网身份配对成功。当前控制、截图与文件传输仍需在MacPhone连接ADB。"));
 }catch(Exception e){runOnUiThread(()->view.setText("配对失败："+e.getMessage()+"\n请确认同一网络、允许MacPhone入站连接，或重新生成二维码。"));}},"MacPhone-pair").start();}).show();
 }
}
